//! An item of a column flex container with a preferred `aspect-ratio` and an
//! `auto` width contributes to the width of its container the width its ratio
//! takes from the height the item states, or the width of its content when it
//! states none (CSS Sizing 4 §5.1). The height the container flexes the item
//! to, or its flex basis, is not a height the item states: an inline-flex
//! container of `height: 100px` with an item of `height: 50px`, `flex: 1` and
//! a 1 / 1 ratio is `50px` wide, and the item is `100px` wide where the
//! container leaves it room, as the flexed height gives. The container is as
//! wide as that width whether it is an inline-flex box, a float, an absolutely
//! positioned box, a `min-content`, `max-content` or `fit-content` box, or an
//! item of another container. The expected border boxes were recorded from
//! Chromium for the same markup in an 800px by 600px viewport, with the body
//! margin of 8px and an image of 20x50 pixels.

use raikiri_html::{
    FontCollectionBuilder, LayoutOptions, LayoutStatus, RenderResources, layout,
    parse_html_with_resources,
};
use raikiri_traits::{
    IntrinsicBox, LayoutConfig, PageDefaults, ReplacedResolver, ResolveDisposition,
    ResolvedIntrinsic, ResolverError, ResolverRequest,
};
use url::Url;

const AHEM: &[u8] = include_bytes!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/tests/data/text-autospace/Ahem.ttf"
));

/// Every image is 20x50 pixels, a 2:5 aspect ratio.
struct Portrait;

impl ReplacedResolver for Portrait {
    fn resolve(&self, _request: ResolverRequest<'_>) -> Result<ResolvedIntrinsic, ResolverError> {
        Ok(ResolvedIntrinsic::new(
            IntrinsicBox::new(20.0, 50.0),
            ResolveDisposition::Ok,
        ))
    }
}

/// A border box `(x, y, width, height)`.
type Rect = (f32, f32, f32, f32);

/// A case: its name, its markup, and the border boxes by id.
type Case = (&'static str, &'static str, &'static [(&'static str, Rect)]);

/// The border boxes of the elements of `body` with an `id` on the first page.
fn border_boxes(body: &str) -> Vec<(String, Rect)> {
    let html = format!(
        "<!DOCTYPE html><style>@page {{ size: 800px 600px; margin: 0 }} \
         body {{ margin: 8px; font: 10px/10px Ahem }} div {{ box-sizing: border-box }}</style>{body}"
    );
    let fonts = FontCollectionBuilder::new()
        .font_bytes("Ahem", AHEM.to_vec())
        .build()
        .expect("fonts");
    let resources = RenderResources::new()
        .fonts(fonts)
        .base_url(Url::parse("https://flex.test/document.html").expect("url"))
        .replaced_resolver(&Portrait);
    let doc = parse_html_with_resources(html.as_bytes(), &resources).expect("parse");
    let status = layout(
        &doc,
        PageDefaults::default(),
        LayoutConfig::default(),
        LayoutOptions::new().resources(&resources),
    )
    .expect("layout");
    let LayoutStatus::Completed(result) = status else {
        panic!("expected a complete layout");
    };
    let page = result.pages().next().expect("a page");
    let dom = page.dom();
    page.fragments()
        .filter_map(|fragment| {
            let id = dom.attr(fragment.node(), "id")?;
            let rect = fragment.rect();
            Some((id.to_owned(), (rect.x, rect.y, rect.width, rect.height)))
        })
        .collect()
}

/// Layout units are 1/64px; allow a little more for the 32-bit sums.
const TOLERANCE: f32 = 0.02;

fn check(name: &str, body: &str, expected: &[(&str, Rect)]) {
    let actual = border_boxes(body);
    for &(id, (x, y, width, height)) in expected {
        let found = actual
            .iter()
            .find(|(box_id, _)| box_id == id)
            .unwrap_or_else(|| panic!("{name}: no fragment for #{id} in {body}"))
            .1;
        let close = |a: f32, b: f32| (a - b).abs() <= TOLERANCE;
        assert!(
            close(found.0, x)
                && close(found.1, y)
                && close(found.2, width)
                && close(found.3, height),
            "{name}: {body}: #{id} is {found:?}, expected {:?}",
            (x, y, width, height)
        );
    }
}

/// Run every case whose name satisfies `select`, and make sure some do.
fn check_group(select: fn(&str) -> bool) {
    let cases: Vec<&Case> = CASES.iter().filter(|case| select(case.0)).collect();
    assert!(!cases.is_empty(), "no case selected");
    for &&(name, body, expected) in &cases {
        check(name, body, expected);
    }
}

fn container_kinds(name: &str) -> bool {
    name.starts_with("a_")
}

#[test]
fn a_shrink_to_fit_column_container_is_as_wide_as_the_stated_heights_give() {
    check_group(container_kinds);
}

fn item_kinds(name: &str) -> bool {
    name.starts_with("b_")
}

#[test]
fn an_item_contributes_the_height_it_states_whatever_its_other_sizes_are() {
    check_group(item_kinds);
}

fn nested_containers(name: &str) -> bool {
    name.starts_with("c_")
}

#[test]
fn a_column_container_in_another_container_contributes_the_same_width() {
    check_group(nested_containers);
}

fn stretched_items(name: &str) -> bool {
    name.starts_with("d_")
}

#[test]
fn a_stretched_item_contributes_the_height_of_its_container_less_its_margins() {
    check_group(stretched_items);
}

fn narrow_parents(name: &str) -> bool {
    name.starts_with("e_")
}

#[test]
fn a_column_container_in_a_narrow_parent_is_as_wide_as_the_room_and_the_items_leave_it() {
    check_group(narrow_parents);
}

/// A case that no group selects would never be run.
#[test]
fn every_case_is_in_a_group() {
    let groups: &[fn(&str) -> bool] = &[
        container_kinds,
        item_kinds,
        nested_containers,
        stretched_items,
        narrow_parents,
    ];
    for case in CASES {
        assert!(
            groups.iter().any(|group| group(case.0)),
            "{}: no group runs it",
            case.0
        );
    }
}

